INSERT INTO `questions` VALUES (1,'TKP','pribadi','Profesionalisme','sedang','Ada peluang promosi tapi bersaing dengan rekan. Sikap Anda adalah... (Var 1)','Menjatuhkan rekan','Mengeluh','Fokus pada kinerja dan fair competition','Mencari alasan','Mengabaikan','C',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan integritas dan profesionalisme. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(2,'TKP','pribadi','Profesionalisme','sedang','Ada kesalahan dalam pekerjaan Anda. Tindakan Anda adalah... (Var 2)','Menyembunyikan kesalahan','Menyalahkan orang lain','Mengakui dan memperbaiki dengan segera','Mengabaikan','Mencari alasan','C',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan integritas dan tanggung jawab. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(3,'TKP','pribadi','Profesionalisme','sedang','Ada tugas mendesak dan tugas rutin. Prioritas Anda adalah... (Var 3)','Mengerjakan yang mudah dulu','Menolak tugas mendesak','Mengelola waktu dan komunikasi dengan atasan','Mengerjakan asal-asalan','Mencari alasan','B',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan kemampuan manajemen waktu dan komunikasi. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(4,'TKP','pribadi','Profesionalisme','sedang','Atasan memberi kritik keras atas kinerja Anda. Respon Anda adalah... (Var 4)','Membela diri dengan marah','Diam dan tersinggung','Menerima masukan dan bertanya cara perbaikan','Mengeluh ke rekan','Mencari alasan','C',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan sikap menerima masukan dan komitmen perbaikan. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(5,'TKP','pribadi','Profesionalisme','sedang','Ada tugas mendesak dan tugas rutin. Prioritas Anda adalah... (Var 5)','Mengerjakan yang mudah dulu','Menolak tugas mendesak','Mengelola waktu dan komunikasi dengan atasan','Mengerjakan asal-asalan','Mencari alasan','B',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan kemampuan manajemen waktu dan komunikasi. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(6,'TKP','pribadi','Profesionalisme','sedang','Ada peluang promosi tapi bersaing dengan rekan. Sikap Anda adalah... (Var 6)','Menjatuhkan rekan','Mengeluh','Fokus pada kinerja dan fair competition','Mencari alasan','Mengabaikan','C',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan integritas dan profesionalisme. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(7,'TKP','pribadi','Profesionalisme','sedang','Ada konflik kepentingan antara pekerjaan dan pribadi. Sikap Anda adalah... (Var 7)','Mengutamakan kepentingan pribadi','Mengeluh','Mengutamakan kepentingan pekerjaan dengan transparansi','Mencari alasan','Mengabaikan','A',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan integritas dan profesionalisme. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(8,'TKP','pribadi','Profesionalisme','sedang','Ada peluang kenaikan gaji tapi dengan cara tidak etis. Sikap Anda adalah... (Var 8)','Mengambil peluang','Minta nominal lebih tinggi','Menolak dan mengikuti prosedur yang benar','Mengabaikan','Mencari alasan','C',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan integritas dan keberanian melawan korupsi. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(9,'TKP','pribadi','Profesionalisme','sedang','Rekan melakukan pelanggaran etika. Tindakan Anda adalah... (Var 9)','Ikut melakukan','Diam saja','Menegur dan melaporkan jika perlu','Melaporkan tanpa konfirmasi','Mengabaikan','C',5,NULL,NULL,NULL,NULL,NULL,'Jawaban C menunjukkan integritas dan kepemimpinan. Ini nilai tertinggi dalam profesionalisme.',NULL,NULL,22,NULL,NULL,0,'2026-06-06 06:36:03',0,NULL,1),(10,'TKP','pribad