INSERT INTO `rekomendasi_materi` VALUES (1,'TWK','Nasionalisme','pages/materi.php?subtes=TWK&topik=Nasionalisme','Tingkatkan rasa cinta tanah air dengan memahami sejarah perjuangan bangsa.',1,1),(2,'TWK','Integritas','pages/materi.php?subtes=TWK&topik=Integritas','Integritas adalah kunci sukses. Belajar etika dan anti korupsi.',1,2),(3,'TWK','Bela Negara','pages/materi.php?subtes=TWK&topik=Bela+Negara','Pahami konsep bela negara dalam konteks modern.',1,3),(4,'TWK','Pilar Negara','pages/materi.php?subtes=TWK&topik=Pilar+Negara','Kuasai Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika.',1,4),(5,'TWK','Bahasa Indonesia','pages/materi.php?subtes=TWK&topik=Bahasa+Indonesia','Perbanyak latihan EYD, peribahasa, dan kosakata baku.',1,5),(6,'TIU','Analogi Verbal','pages/materi.php?subtes=TIU&tipe=verbal&topik=Analogi','Latih kemampuan asosiasi kata dengan latihan rutin.',1,6),(7,'TIU','Silogisme','pages/materi.php?subtes=TIU&tipe=verbal&topik=Silogisme','Pahami struktur premis-premis untuk menyimpulkan logis.',1,7),(8,'TIU','Analitis','pages/materi.php?subtes=TIU&tipe=verbal&topik=Analitis','Kerjakan soal TPA analitis dengan membuat tabel/diagram.',1,8),(9,'TIU','Berhitung Cepat','pages/materi.php?subtes=TIU&tipe=numerik&topik=Berhitung','Kuasai trik perhitungan cepat dan operasi dasar.',1,9),(10,'TIU','Deret Angka','pages/materi.php?subtes=TIU&tipe=numerik&topik=Deret','Identifikasi pola aritmatika, geometri, dan kombinasi.',1,10),(11,'TIU','Perbandingan','pages/materi.php?subtes=TIU&tipe=numerik&topik=Perbandingan','Pahami rasio, skala, dan proporsi dengan latihan soal cerita.',1,11),(12,'TIU','Soal Cerita','pages/materi.php?subtes=TIU&tipe=numerik&topik=Cerita','Pelajari teknik menerjemahkan soal cerita ke persamaan matematika.',1,12),(13,'TIU','Figural Analogi','pages/materi.php?subtes=TIU&tipe=figural&topik=Analogi','Latih pengenalan pola visual dan transformasi gambar.',1,13),(14,'TIU','Figural Ketidaksamaan','pages/materi.php?subtes=TIU&tipe=figural&topik=Ketidaksamaan','Cari perbedaan detail dalam gambar dengan fokus dan teliti.',1,14),(15,'TIU','Figural Serial','pages/materi.php?subtes=TIU&tipe=figural&topik=Serial','Amati urutan pola visual dan prediksi gambar selanjutnya.',1,15),(16,'TKP','Pelayanan Publik','pages/materi.php?subtes=TKP&topik=Pelayanan+Publik','Pelajari prinsip pelayanan prima dan penanganan keluhan.',1,16),(17,'TKP','Jejaring Kerja','pages/materi.php?subtes=TKP&topik=Jejaring+Kerja','Pahami kerja sama tim, koordinasi, dan komunikasi efektif.',1,17),(18,'TKP','Sosial Budaya','pages/materi.php?subtes=TKP&topik=Sosial+Budaya','Latih empati dan penghormatan terhadap keberagaman.',1,18),(19,'TKP','Teknologi Informasi','pages/materi.php?subtes=TKP&topik=TI','Pahami etika digital dan pemanfaatan teknologi untuk pelayanan.',1,19),(20,'TKP','Profesionalisme','pages/materi.php?subtes=TKP&topik=Profesionalisme','Kembangkan sikap profesional: integritas, komitmen, dan tanggung jawab.',1,20);
